local function getF3XRemote()
    local char = LocalPlayer.Character
    local bp = LocalPlayer:FindFirstChild("Backpack")
    if char and char:FindFirstChildOfClass("Tool") and char:FindFirstChildOfClass("Tool"):FindFirstChild("SyncAPI") then
        return char:FindFirstChildOfClass("Tool").SyncAPI:FindFirstChild("ServerEndpoint")
    elseif bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and t:FindFirstChild("SyncAPI") then
                return t.SyncAPI:FindFirstChild("ServerEndpoint")
            end
        end
    end
    return nil
end

local function runHD(cmd)
    local ok, folder = pcall(function() return ReplicatedStorage:WaitForChild("HDAdminHDClient", 2) end)
    if ok and folder then
        local req = folder:WaitForChild("Signals"):WaitForChild("RequestCommand")
        req:InvokeServer(cmd)
    else
        warn("HD Admin not found")
    end
end

